#!/usr/bin/env node
/**
 * Generate PascalCase named remix icon factories from vendored glyph JSON.
 * One module per icon (tree-shake friendly) + barrel re-exports.
 */
import {
  readdirSync,
  writeFileSync,
  mkdirSync,
  existsSync,
  rmSync,
} from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const generated = path.join(root, "src/generated/heroicons");

function kebabToPascal(name) {
  return name
    .split("-")
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join("");
}

function generateVariant(variant, factory) {
  const dir = path.join(generated, variant);
  if (!existsSync(dir)) {
    console.warn(`[ui-icons] skip ${variant}: no ${dir}`);
    return [];
  }
  const names = readdirSync(dir)
    .filter((f) => f.endsWith(".json"))
    .map((f) => f.replace(/\.json$/, ""))
    .sort();

  const outDir = path.join(root, "src/24", variant);
  rmSync(outDir, { recursive: true, force: true });
  mkdirSync(outDir, { recursive: true });

  const barrel = [
    `/** Auto-generated by scripts/generate-named.mjs — do not edit. */`,
    ``,
  ];

  for (const name of names) {
    const pascal = kebabToPascal(name) + "Icon";
    const file = `${name}.ts`;
    writeFileSync(
      path.join(outDir, file),
      [
        `/** Auto-generated — Heroicons ${variant} \`${name}\`. */`,
        `import { ${factory} } from "../../create-icon.tsx";`,
        `import glyphs from "../../generated/heroicons/${variant}/${name}.json" with { type: "json" };`,
        `export const ${pascal} = ${factory}(glyphs);`,
        `export default ${pascal};`,
        ``,
      ].join("\n"),
    );
    barrel.push(`export { ${pascal} } from "./${variant}/${name}.ts";`);
  }

  const barrelPath = path.join(root, "src/24", `${variant}.ts`);
  writeFileSync(barrelPath, barrel.join("\n") + "\n");
  console.log(
    `[ui-icons] wrote ${outDir} (${names.length} icons) + ${barrelPath}`,
  );
  return names;
}

const outline = generateVariant("outline", "createOutlineIcon");
const solid = generateVariant("solid", "createSolidIcon");

const manifestPath = path.join(generated, "manifest.ts");
writeFileSync(
  manifestPath,
  [
    `/** Auto-generated by scripts/generate-named.mjs — do not edit. */`,
    ``,
    `export const HEROICONS_OUTLINE_NAMES = Object.freeze(${JSON.stringify(outline, null, 2)} as const);`,
    ``,
    `export const HEROICONS_SOLID_NAMES = Object.freeze(${JSON.stringify(solid, null, 2)} as const);`,
    ``,
    `export const HEROICONS_OUTLINE_COUNT = ${outline.length};`,
    `export const HEROICONS_SOLID_COUNT = ${solid.length};`,
    ``,
  ].join("\n"),
);
console.log(`[ui-icons] wrote ${manifestPath}`);
